import{_ as e,c as t,o as s,a4 as a}from"./chunks/framework.ttppV29E.js";const r="/assets/aireframe-tab.uL8_c7OG.png",o="/assets/aireframe-edit-user.BMJrA8Vq.png",n="/assets/aireframe-totp-from-qr.BOr384_7.png",i="/assets/aireframe-totp-wrong-user.DVOGt279.png",w=JSON.parse('{"title":"AireFrame Settings","description":"","frontmatter":{},"headers":[],"relativePath":"docs/using-the-test-editor/aireframe-settings.md","filePath":"docs/using-the-test-editor/aireframe-settings.md","lastUpdated":1790836118000}'),d={name:"docs/using-the-test-editor/aireframe-settings.md"},h=a('<h1 id="aireframe-settings" tabindex="-1">AireFrame Settings <a class="header-anchor" href="#aireframe-settings" aria-label="Permalink to &quot;AireFrame Settings&quot;">​</a></h1><p>The <strong>FRAME</strong> tab of the Test Set Settings panel configures how your tests log into AireFrame and which users they can act as. These settings map to the <code>AireFrame</code> section of your test set&#39;s <code>Configuration.json</code>.</p><p>If a test set has no AireFrame configuration yet, the tab shows a single <strong>Add AireFrame Settings</strong> button. Click it to create the section, then fill in the settings below.</p><p><img src="'+r+'" alt="AireFrame Settings"></p><h2 id="assertion-retry-seconds" tabindex="-1">Assertion Retry Seconds <a class="header-anchor" href="#assertion-retry-seconds" aria-label="Permalink to &quot;Assertion Retry Seconds&quot;">​</a></h2><p>The number of seconds to retry subject assertions for before failing. AireFrame can take a moment to show data that has just been written, so a short retry window makes tests less brittle. Leave it at <code>0</code> to fail on the first unsuccessful check.</p><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>Each user listed here can be referenced from your Gherkin, for example:</p><div class="language-gherkin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gherkin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">When </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">we login to AireFrame as </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;E2E Clinician&#39;</span></span></code></pre></div><p>The table lists each configured user by <strong>Name</strong>. Use the pencil icon to edit a user, the bin icon to remove one (you will be asked to confirm), and <strong>Add User</strong> to add another.</p><p>See <a href="./../command-library/aireframe-commands.html">AireFrame Commands</a> for the full set of commands these users can drive.</p><h2 id="adding-or-editing-a-user" tabindex="-1">Adding or editing a user <a class="header-anchor" href="#adding-or-editing-a-user" aria-label="Permalink to &quot;Adding or editing a user&quot;">​</a></h2><p><img src="'+o+'" alt="Edit AireFrame User"></p><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>A short, readable alias for the user. This is the name you use in your Gherkin, so keep it stable once tests refer to it.</td></tr><tr><td><strong>Username</strong></td><td>The user&#39;s AireFrame login, which must be an email address.</td></tr><tr><td><strong>Password</strong></td><td>The user&#39;s password. Stored in AireVault, never in your repository.</td></tr><tr><td><strong>TOTP Secret</strong></td><td>The Base32 secret used to generate 2FA codes, for users who have two-factor authentication enabled. Also stored in AireVault.</td></tr></tbody></table><h3 id="how-passwords-and-totp-secrets-are-stored" tabindex="-1">How passwords and TOTP secrets are stored <a class="header-anchor" href="#how-passwords-and-totp-secrets-are-stored" aria-label="Permalink to &quot;How passwords and TOTP secrets are stored&quot;">​</a></h3><p>Both secrets are written straight to <strong>AireVault</strong> when you click <strong>Save</strong>, and are never written into <code>Configuration.json</code> — so they are never committed to your Git repository.</p><p>Two consequences worth knowing:</p><ul><li>The test set needs both a <strong>Target Tenancy</strong> and a <strong>Target Instance</strong>, both in General Settings, before secrets can be stored, because together they identify where in AireVault the secret belongs. The dialog will tell you if either is missing.</li><li>Both fields are always shown blank when you open the dialog, because a stored secret cannot be read back. <strong>Leave a field blank to keep its current value</strong>, and only fill it in when you want to replace what is stored.</li></ul><blockquote><p><strong>Note:</strong> If a test set already carries a password or TOTP secret in plaintext in its <code>Configuration.json</code>, that value takes priority over AireVault when tests run. Saving a secret through this dialog clears the plaintext value for you, so the value you just stored is the one that gets used.</p></blockquote><h2 id="reading-a-totp-secret-from-a-qr-code" tabindex="-1">Reading a TOTP secret from a QR code <a class="header-anchor" href="#reading-a-totp-secret-from-a-qr-code" aria-label="Permalink to &quot;Reading a TOTP secret from a QR code&quot;">​</a></h2><p>Rather than transcribing a 32-character secret by hand, you can take the QR code straight from AireFrame&#39;s two-factor setup page:</p><ol><li>In AireFrame, start setting up two-factor authentication for the user. The page shows a QR code alongside the key in text form.</li><li>Take a screenshot of that page and copy it to your clipboard.</li><li>Open the user in AireAssert and press <strong>Ctrl+V</strong> anywhere in the dialog.</li></ol><p>AireAssert reads the QR code, fills in the <strong>TOTP Secret</strong> field, and shows the secret in plain text so you can check it against the key printed next to the QR code. Nothing is uploaded — the image is read in your browser.</p><p><img src="'+n+'" alt="TOTP secret read from a QR code"></p><p>The panel underneath shows the <strong>current 6-digit code</strong> for that secret, with a countdown to the next one and a button to copy it. AireFrame&#39;s setup page asks you to enter a code to confirm enrolment, so you can complete the setup from here without adding the user to an authenticator app first.</p><p>Click <strong>Save</strong> once you are happy with the secret. The code panel is only a convenience — it is generated in your browser from the secret in the field and is not stored anywhere.</p><h3 id="checking-you-scanned-the-right-user" tabindex="-1">Checking you scanned the right user <a class="header-anchor" href="#checking-you-scanned-the-right-user" aria-label="Permalink to &quot;Checking you scanned the right user&quot;">​</a></h3><p>Because a TOTP secret is a meaningless string, scanning the wrong QR code out of a busy screenshot is easy to do and hard to notice — the tests simply fail to log in later. AireAssert reads the account name out of the QR code and shows it back to you, and warns when it does not match the username on the user you are editing:</p><p><img src="'+i+'" alt="A QR code issued to a different user"></p><p>This is only a warning, not a block: the name on the QR code and the AireFrame username can legitimately differ. Check it before saving.</p><h3 id="qr-codes-aireassert-cannot-use" tabindex="-1">QR codes AireAssert cannot use <a class="header-anchor" href="#qr-codes-aireassert-cannot-use" aria-label="Permalink to &quot;QR codes AireAssert cannot use&quot;">​</a></h3><p>AireAssert generates 2FA codes using the standard settings that AireFrame issues — SHA1, 6 digits and a 30-second period. If a QR code asks for anything else, it is rejected with a message naming the problem rather than being stored, because the stored secret would generate codes that never work. The same applies to counter-based (HOTP) authenticator codes, which AireAssert does not support.</p><p>If no QR code can be found in the image, try a screenshot cropped more tightly around the code.</p><h2 id="entering-a-secret-by-hand" tabindex="-1">Entering a secret by hand <a class="header-anchor" href="#entering-a-secret-by-hand" aria-label="Permalink to &quot;Entering a secret by hand&quot;">​</a></h2><p>You can still type or paste the secret instead. Both forms that AireFrame shows are accepted:</p><ul><li>the plain key, for example <code>JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP</code></li><li>the spaced form printed next to the QR code, for example <code>JBSW Y3DP EHPK 3PXP JBSW Y3DP EHPK 3PXP</code></li></ul><p>Spacing and letter case are tidied up for you when you leave the field. A TOTP secret must be Base32, which means only the letters <code>A</code>–<code>Z</code> and the digits <code>2</code>–<code>7</code>; anything else is rejected when you save. You can also paste the full <code>otpauth://</code> link if you have it.</p><p>Use the eye icon at the end of the field to show or hide whatever is currently entered.</p>',38),c=[h];function l(u,g,p,m,f,y){return s(),t("div",null,c)}const k=e(d,[["render",l]]);export{w as __pageData,k as default};
